package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="complaints") public class Complaint { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="complaint_number",nullable=false,unique=true,length=50) private String complaintNumber; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id",nullable=false) private Customer customer; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private Order order; @Column(nullable=false,length=200) private String subject; @Column(nullable=false) private String description; @Column(nullable=false,length=30) private String status; @Column(nullable=false,length=20) private String priority; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; @Column(name="resolved_at") private OffsetDateTime resolvedAt; public UUID getId(){return id;} public String getComplaintNumber(){return complaintNumber;} public void setComplaintNumber(String v){complaintNumber=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} }
